func jsonEqual(_ a: Any, _ b: Any) -> Bool {
    if a is NSNull && b is NSNull { return true }
    if a is NSNull || b is NSNull { return false }
    if let da = a as? [String: Any], let db = b as? [String: Any] {
        if da.count != db.count { return false }
        for (k, va) in da {
            guard let vb = db[k] else { return false }
            if !jsonEqual(va, vb) { return false }
        }
        return true
    }
    if let aa = a as? [Any], let ab = b as? [Any] {
        if aa.count != ab.count { return false }
        for i in 0..<aa.count {
            if !jsonEqual(aa[i], ab[i]) { return false }
        }
        return true
    }
    if let sa = a as? String, let sb = b as? String { return sa == sb }
    if let na = a as? NSNumber, let nb = b as? NSNumber {
        let aIsBool = CFGetTypeID(na) == CFBooleanGetTypeID()
        let bIsBool = CFGetTypeID(nb) == CFBooleanGetTypeID()
        if aIsBool != bIsBool { return false }
        if aIsBool { return na.boolValue == nb.boolValue }
        return na.doubleValue == nb.doubleValue
    }
    return false
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let da = a as? [String: Any], let db = b as? [String: Any] {
        var result = da
        for (key, bVal) in db {
            if let aVal = da[key] {
                result[key] = deepMerge(aVal, bVal)
            } else {
                result[key] = bVal
            }
        }
        return result
    }
    if let aa = a as? [Any], let ab = b as? [Any] {
        var result: [Any] = aa
        for item in ab {
            if !result.contains(where: { jsonEqual($0, item) }) {
                result.append(item)
            }
        }
        return result
    }
    return b
}

