import * as http from "http";

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

function httpGet(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = "";
      res.on("data", (chunk: string) => {
        data += chunk;
      });
      res.on("end", () => {
        resolve(data);
      });
      res.on("error", (err: Error) => {
        reject(err);
      });
    }).on("error", (err: Error) => {
      reject(err);
    });
  });
}

async function main(): Promise<void> {
  const response: string = await httpGet("http://127.0.0.1:18923/api/products");
  const products: Product[] = JSON.parse(response);

  const filtered: Product[] = products.filter((p) => p.price > 50.00);
  filtered.sort((a, b) => a.name.localeCompare(b.name));

  const lines: string[] = [];
  lines.push("=== Filtered Products (price > $50.00) ===");
  lines.push("");

  for (const p of filtered) {
    lines.push(`${p.name}: $${p.price.toFixed(2)}`);
  }

  lines.push("");
  lines.push(`Count: ${filtered.length}`);
  const total: number = filtered.reduce((sum, p) => sum + p.price, 0);
  lines.push(`Total: $${total.toFixed(2)}`);

  console.log(lines.join("\n"));
}

