            json_read_file[json_read_pos] == '\t' ||
            json_read_file[json_read_pos] == '\n' ||
            json_read_file[json_read_pos] == '\r'))
        json_read_pos++;
}

static char *parse_string(void) {
    if (json_read_pos >= json_read_len || json_read_file[json_read_pos] != '"') return NULL;
    json_read_pos++;
    size_t start = json_read_pos;
    while (json_read_pos < json_read_len && json_read_file[json_read_pos] != '"') {
        if (json_read_file[json_read_pos] == '\\') json_read_pos++;
        json_read_pos++;
    }
    size_t len = json_read_pos - start;
    char *s = (char *)malloc(len + 1);
    size_t j = 0;
    for (size_t i = start; i < json_read_pos; i++) {
        if (json_read_file[i] == '\\' && i + 1 < json_read_pos) {
            i++;
            switch (json_read_file[i]) {
                case 'n': s[j++] = '\n'; break;
                case 't': s[j++] = '\t'; break;
                case 'r': s[j++] = '\r'; break;
                case '\\': s[j++] = '\\'; break;
                case '"': s[j++] = '"'; break;
                case '/': s[j++] = '/'; break;
                default: s[j++] = json_read_file[i]; break;
            }
        } else {
            s[j++] = json_read_file[i];
        }
    }
    s[j] = '\0';
    if (json_read_pos < json_read_len) json_read_pos++;
    return s;
}

