struct HeapItem: Comparable {
    let node: String
    let dist: Int
    static func < (lhs: HeapItem, rhs: HeapItem) -> Bool {
        return lhs.dist < rhs.dist
    }
}

func heapifyUp(_ arr: inout [HeapItem], _ i: Int) {
    var i = i
    while i > 0 {
        let parent = (i - 1) / 2
        if arr[i] < arr[parent] {
            arr.swapAt(i, parent)
            i = parent
        } else {
            break
        }
    }
}

func heapifyDown(_ arr: inout [HeapItem], _ i: Int) {
    var i = i
    let n = arr.count
    while true {
        var smallest = i
        let left = 2 * i + 1
        let right = 2 * i + 2
        if left < n && arr[left] < arr[smallest] {
            smallest = left
        }
        if right < n && arr[right] < arr[smallest] {
            smallest = right
        }
        if smallest != i {
            arr.swapAt(i, smallest)
            i = smallest
        } else {
            break
        }
    }
}

func push(_ arr: inout [HeapItem], _ item: HeapItem) {
    arr.append(item)
    heapifyUp(&arr, arr.count - 1)
}

