    let contents: [URL]
    do {
        contents = try fm.contentsOfDirectory(at: url, includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey], options: [])
    } catch {
        return
    }
    for item in contents {
        let name = item.lastPathComponent
        let rel = relativePath.isEmpty ? name : relativePath + "/" + name

        let attrs = try? fm.attributesOfItem(atPath: item.path)
        let fileType = attrs?[.type] as? FileAttributeType
        if fileType == .typeSymbolicLink {
            continue
        }

        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: item.path, isDirectory: &isDir) else { continue }

        if isDir.boolValue {
            walk(url: item, relativePath: rel)
        } else {
            let data = try? Data(contentsOf: item)
            let byteCount = data?.count ?? 0
            let content = data.flatMap { String(data: $0, encoding: .utf8) } ?? ""
            let lineCount: Int
            if content.isEmpty {
                lineCount = 0
            } else {
                var lines = content.components(separatedBy: "\n")
                if lines.last == "" {
                    lines.removeLast()
                }
                lineCount = lines.count
            }
            let ext = (name as NSString).pathExtension
            let extStr = ext.isEmpty ? "" : "." + ext
            files.append((relativePath: rel, ext: extStr, lines: lineCount, chars: byteCount))
        }
    }
}

