function walk(dir: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];
  let realDir: string;
  try {
    realDir = fs.realpathSync(dir);
  } catch {
    return results;
  }
  if (visited.has(realDir)) return results;
  visited.add(realDir);

  const entries = fs.readdirSync(dir);
  for (const name of entries) {
    const fullPath = path.join(dir, name);
    let lstat: fs.Stats;
    try {
      lstat = fs.lstatSync(fullPath);
    } catch {
      continue;
    }

    if (lstat.isSymbolicLink()) {
      continue;
    }

    if (lstat.isDirectory()) {
      const sub = walk(fullPath, visited);
      for (const f of sub) {
        results.push(f);
      }
    } else if (lstat.isFile()) {
      const relPath = path
        .relative(rootDir, fullPath)
        .split(path.sep)
        .join("/");
      const buffer = fs.readFileSync(fullPath);
      const chars = buffer.length;
      const content = buffer.toString("utf-8");
      let lines: number;
      if (content.length === 0) {
        lines = 0;
      } else {
        const parts = content.split("\n");
        lines = parts[parts.length - 1] === "" ? parts.length - 1 : parts.length;
      }
      results.push({ relPath, lines, chars });
    }
  }
  return results;
}

