static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t capacity = 256;
    size_t length = 0;
    char *buffer = (char *)malloc(capacity);
    if (!buffer) { pclose(fp); return NULL; }

    size_t n;
    while ((n = fread(buffer + length, 1, capacity - length - 1, fp)) > 0) {
        length += n;
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *tmp = (char *)realloc(buffer, capacity);
            if (!tmp) { free(buffer); pclose(fp); return NULL; }
            buffer = tmp;
        }
    }
    buffer[length] = '\0';
    pclose(fp);

    while (length > 0 && (buffer[length - 1] == '\n' || buffer[length - 1] == '\r' ||
                          buffer[length - 1] == ' '  || buffer[length - 1] == '\t')) {
        buffer[--length] = '\0';
    }
    return buffer;
}

