const A: number[][] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

function multiply(M1: number[][], M2: number[][]): number[][] {
    const n = M1.length;
    const m = M2[0].length;
    const p = M2.length;
    const R: number[][] = [];
    for (let i = 0; i < n; i++) {
        R[i] = [];
        for (let j = 0; j < m; j++) {
            let sum = 0;
            for (let k = 0; k < p; k++) {
                sum += M1[i][k] * M2[k][j];
            }
            R[i][j] = sum;
        }
    }
    return R;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let result = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) row.push(M[i][k]);
            }
            minor.push(row);
        }
        result += (j % 2 === 0 ? 1 : -1) * M[0][j] * determinant(minor);
    }
    return result;
}

const C = multiply(A, B);
const detC = determinant(C);

function formatMatrix(M: number[][]): string {
    return M.map(row => "  " + row.map(v => String(v).padStart(4)).join(" ")).join("\n");
}

